CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),email VARCHAR(320) UNIQUE NOT NULL,username VARCHAR(50) UNIQUE NOT NULL,full_name VARCHAR(120) NOT NULL,password_hash TEXT,status VARCHAR(30) NOT NULL DEFAULT 'active',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS workspaces(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),owner_user_id UUID NOT NULL REFERENCES users(id),name VARCHAR(160) NOT NULL,slug VARCHAR(120) UNIQUE NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'active',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS workspace_memberships(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,role_key VARCHAR(80) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'active',UNIQUE(workspace_id,user_id));
CREATE TABLE IF NOT EXISTS tenant_registry(workspace_id UUID PRIMARY KEY REFERENCES workspaces(id) ON DELETE CASCADE,database_name VARCHAR(120) UNIQUE NOT NULL,database_host VARCHAR(255) NOT NULL DEFAULT 'postgres',database_port INT NOT NULL DEFAULT 5432,database_user VARCHAR(120) NOT NULL DEFAULT 'postgres',secret_ref TEXT,schema_version VARCHAR(30) NOT NULL DEFAULT '0',status VARCHAR(30) NOT NULL DEFAULT 'provisioning');
CREATE TABLE IF NOT EXISTS subscription_plans(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),key VARCHAR(50) UNIQUE NOT NULL,name VARCHAR(100) NOT NULL,monthly_price NUMERIC(12,2),annual_price NUMERIC(12,2),entitlements JSONB NOT NULL DEFAULT '{}'::jsonb,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS subscriptions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,plan_id UUID NOT NULL REFERENCES subscription_plans(id),status VARCHAR(40) NOT NULL,period_start TIMESTAMPTZ,period_end TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS payments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,provider VARCHAR(40) NOT NULL,provider_payment_id VARCHAR(255),amount NUMERIC(12,2) NOT NULL,currency VARCHAR(10) NOT NULL,status VARCHAR(40) NOT NULL,paid_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
